func ptrCarrierContact(p unsafe.Pointer, c int32) any {
	r := (*carrier.CarrierContact)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CarrierID))
	case 4:
		return &r.Name
	case 5:
		return &r.Title
	case 6:
		return &r.Email
	case 7:
		return &r.Phone
	case 8:
		return &r.IsPrimary
	case 9:
		return &r.ReceivesRateConfirmations
	case 10:
		return &r.Version
	case 11:
		return &r.CreatedAt
	case 12:
		return &r.UpdatedAt
	}
	return nil
}

func valueCarrierContact(p unsafe.Pointer, c int32) any {
	r := (*carrier.CarrierContact)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.CarrierID)
	case 4:
		return r.Name
	case 5:
		if r.Title == "" {
			return nil
		}
		return r.Title
	case 6:
		if r.Email == "" {
			return nil
		}
		return r.Email
	case 7:
		if r.Phone == "" {
			return nil
		}
		return r.Phone
	case 8:
		return r.IsPrimary
	case 9:
		return r.ReceivesRateConfirmations
	case 10:
		return r.Version
	case 11:
		return r.CreatedAt
	case 12:
		return r.UpdatedAt
	}
	return nil
}

func attachCarrierContact(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*carrier.CarrierContact)(p)
	switch rel {
	case 0:
		r.Carrier = (*carrier.Carrier)(child)
	}
}

